package main
import("bufio";"encoding/json";"encoding/base64";"fmt";"os";"time";"github.com/livekit/protocol/auth";"github.com/golang-jwt/jwt/v5")
type In struct{ID string `json:"id"`;Config json.RawMessage `json:"config"`; ConfigRaw string `json:"config_raw"`}
func text(e error)string{if e==nil{return ""};return e.Error()}
func main(){s:=bufio.NewScanner(os.Stdin);s.Buffer(make([]byte,4096),1<<20);enc:=json.NewEncoder(os.Stdout);for s.Scan(){var in In;if e:=json.Unmarshal(s.Bytes(),&in);e!=nil{panic(e)};if in.ConfigRaw!=""{in.Config=json.RawMessage(in.ConfigRaw)};var c auth.RoomConfiguration;direct:=c.UnmarshalJSON(in.Config);now:=time.Now().Unix();payload:=fmt.Sprintf(`{"iss":"f102-owned-api","sub":"f102-actor","nbf":%d,"exp":%d,"unknownTopLevel":{"nested":1},"roomConfig":%s}`,now,now+600,string(in.Config));input:=base64.RawURLEncoding.EncodeToString([]byte(`{"alg":"HS256","typ":"JWT"}`))+"."+base64.RawURLEncoding.EncodeToString([]byte(payload));signature,e:=jwt.SigningMethodHS256.Sign(input,[]byte("f102-owned-secret"));signed:=input+"."+base64.RawURLEncoding.EncodeToString(signature);if e!=nil{panic(e)};p,e:=auth.ParseAPIToken(signed);if e!=nil{panic(e)};_,_,verify:=p.Verify("f102-owned-secret");if e:=enc.Encode(map[string]any{"id":in.ID,"direct_error":text(direct),"verified":verify==nil,"verify_error":text(verify)});e!=nil{panic(e)}};if e:=s.Err();e!=nil{panic(e)}}
